/* eslint-disable no-invalid-this */

'use strict';

// MODULES //

var logger = require( 'debug' );
var isString = require( '@stdlib/assert/is-string' ).isPrimitive;
var isStringArray = require( '@stdlib/assert/is-string-array' ).primitives;
var isSignalReference = require( '@stdlib/plot/vega/base/assert/is-signal-reference' );
var hasEqualValues = require( '@stdlib/array/base/assert/has-equal-values' );
var isCompareOrder = require( '@stdlib/plot/vega/base/assert/is-compare-order' );
var compareOrders = require( '@stdlib/plot/vega/compare/orders' );
var copy = require( '@stdlib/array/base/copy' );
var join = require( '@stdlib/array/base/join' );
var format = require( '@stdlib/string/format' );
var defaults = require( './../defaults.js' );
var changeEvent = require( './../change_event.js' );
var prop = require( './properties.js' );


// VARIABLES //

var debug = logger( 'vega:compare:set:'+prop.name );


// MAIN //

/**
* Sets the desired sort order for each field.
*
* @private
* @param {(string|Array<string>|SignalReference|void)} value - input value
* @throws {TypeError} must be a string, an array of strings, or a SignalReference
* @throws {TypeError} each order value must be a valid order
* @throws {TypeError} when field is a SignalReference, order must also be a SignalReference
* @throws {RangeError} order array length must not exceed field array length
* @returns {void}
*/
function set( value ) {
	var isSigRef;
	var nfields;
	var isStr;
	var opts;
	var i;

	isSigRef = isSignalReference( value );
	if ( isSigRef ) {
		// When order is a SignalReference, field must also be a SignalReference...
		if ( !isSignalReference( this._field ) ) {
			throw new TypeError( format( 'invalid assignment. `%s` must be a signal reference when `field` is a signal reference. Value: `%s`.', prop.name, value ) );
		}
		if ( this[ prop.private ] !== value ) {
			debug( 'Current value: %s. New value: %s.', this[ prop.private ], value );
			this[ prop.private ] = value;
			this.emit( 'change', changeEvent( prop.name ) );
		}
		return;
	}
	isStr = isString( value );
	if ( !isStr ) {
		if ( !isStringArray( value ) ) {
			throw new TypeError( format( 'invalid assignment. `%s` must be a string, an array of strings, or a signal reference. Value: `%s`.', prop.name, value ) );
		}
	}
	if ( isStr ) {
		if ( !isCompareOrder( value ) ) {
			throw new TypeError( format( 'invalid assignment. `%s` must be one of the following: "%s". Value: `%s`.', prop.name, join( compareOrders(), '", "' ), value ) );
		}
		value = [ value ];
	} else {
		// Validate each order value...
		for ( i = 0; i < value.length; i++ ) {
			if ( !isCompareOrder( value[ i ] ) ) {
				throw new TypeError( format( 'invalid assignment. `%s` must be one of the following: "%s". Value: `%s`.', prop.name, join( compareOrders(), '", "' ), value[ i ] ) );
			}
		}
		value = copy( value );
	}

	// If there are fewer order entries than field entries, pad with default 'ascending' values...
	nfields = ( this._field ) ? this._field.length : 0;
	if ( value.length > nfields && nfields > 0 ) {
		throw new RangeError( format( 'invalid assignment. `%s` array length must not exceed the number of fields. Number of fields: `%u`. Value: `%s`.', prop.name, nfields, value ) );
	}
	if ( value.length < nfields ) {
		opts = defaults();
		for ( i = value.length; i < nfields; i++ ) {
			value.push( opts.order[ 0 ] );
		}
	}
	if ( !hasEqualValues( value, this[ prop.private ] ) ) {
		debug( 'Current value: ["%s"]. New value: ["%s"].', join( this[ prop.private ], '", "' ), join( value, '", "' ) );
		this[ prop.private ] = value;
		this.emit( 'change', changeEvent( prop.name ) );
	}
}


// EXPORTS //

module.exports = set;
